<h2>Encode or decode UTF-8 text</h2><p class="lead">Convert text to Base64 or decode Base64 back to text locally in the browser.</p><div class="field"><label for="input">Input</label><textarea id="input" style="min-height:180px">Hello ToolboxKart 👋</textarea></div><div class="tool-actions"><button class="btn btn-primary" id="encode">Encode Base64</button><button class="btn btn-secondary" id="decode">Decode Base64</button><button class="btn btn-secondary" id="copy">Copy output</button></div><div id="status"></div><div class="result-box"><pre class="code-output" id="out"></pre></div><div class="notice"><strong>Base64 is encoding, not encryption.</strong> Anyone can decode it; do not use it to protect secrets.</div>
<script>(()=>{const $=i=>document.getElementById(i);function enc(s){const bytes=new TextEncoder().encode(s);let bin='';bytes.forEach(b=>bin+=String.fromCharCode(b));return btoa(bin)}function dec(s){const bin=atob(s.replace(/\s/g,'')),bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));return new TextDecoder().decode(bytes)}$('encode').onclick=()=>{try{$('out').textContent=enc($('input').value);$('status').innerHTML='<div class="notice"><strong class="success">Encoded successfully</strong></div>'}catch(e){$('status').innerHTML='<div class="notice"><strong class="danger">Could not encode input.</strong></div>'}};$('decode').onclick=()=>{try{$('out').textContent=dec($('input').value);$('status').innerHTML='<div class="notice"><strong class="success">Decoded successfully</strong></div>'}catch(e){$('out').textContent='';$('status').innerHTML='<div class="notice"><strong class="danger">Input is not valid Base64.</strong></div>'}};$('copy').onclick=()=>tkCopy($('out').textContent);$('encode').click()})();</script>
